      summary: "阿塔尼斯以经典星灵单位作为部队核心。虽然这些单位本身较为脆弱，但亚顿之矛提供的技能可以提高其生存能力，弥补部队弱点。<br><br>阿塔尼斯的机制较为简单，但玩家必须时刻关注部队存活。充分了解敌方兵种组合后，可以用阿塔尼斯的部队控制整波敌军，或先用亚顿之矛削弱进攻波。",
